from itertools import count, islice
from finestre import finestre, medie_mobili


def test_finestre():
    assert list(finestre([1, 2, 3, 4], 2)) == [(1, 2), (2, 3), (3, 4)]
    assert list(finestre([1, 2], 3)) == []


def test_infinito():
    assert list(islice(finestre(count(), 3), 2)) == [(0, 1, 2), (1, 2, 3)]


def test_medie():
    assert list(medie_mobili([2, 4, 6, 8], 2)) == [3.0, 5.0, 7.0]
